(6713222, 1004078, 58610, '<td valign="top">The buildings aren''t quite sharp, and your horizon seems tilted (could just be the perspective). Love the gradation from bright to dark with everything in between. Nice subject.</td>', 'The buildings aren''t quite sharp, and your horizon seems tilted (could just be the perspective). Love the gradation from bright to dark with everything in between. Nice subject.', '2012-03-16 20:38:10.000000', NULL, 1),
(6713223, 1004651, 58610, '<td valign="top">Wonderful reflections, but overall a little too busy for my taste.</td>', 'Wonderful reflections, but overall a little too busy for my taste.', '2012-03-16 20:39:07.000000', NULL, 1),
(6713224, 1004676, 58610, '<td valign="top">Love the overall feel of this. Very moody. The sky atmosphere really works with the oceanscape.</td>', 'Love the overall feel of this. Very moody. The sky atmosphere really works with the oceanscape.', '2012-03-16 20:40:11.000000', NULL, 1),
(6713233, 1004788, 58610, '<td valign="top">Something in the pp throws me off. Seems as though the sky doesn''t go with the foreground. The trees on the horizon have a backlighting that seems unnatural like you''ve blended two exposures but didn''t feather at the skyline. Still, I like the perspective of the shot and the texture is very interesting.</td>', 'Something in the pp throws me off. Seems as though the sky doesn''t go with the foreground. The trees on the horizon have a backlighting that seems unnatural like you''ve blended two exposures but didn''t feather at the skyline. Still, I like the perspective of the shot and the texture is very interesting.', '2012-03-16 20:45:58.000000', NULL, 1),
(6713244, 1004688, 58610, '<td valign="top">Great scene, but not quite sharp enough. Needed a little more brightness in the snow IMO, and I think it would have been legal to have cloned out that telephone pole, but you''d want to check with the site council first.</td>', 'Great scene, but not quite sharp enough. Needed a little more brightness in the snow IMO, and I think it would have been legal to have cloned out that telephone pole, but you''d want to check with the site council first.', '2012-03-16 20:50:20.000000', NULL, 1),
(6713249, 1004758, 58610, '<td valign="top">Boom!</td>', 'Boom!', '2012-03-16 20:52:27.000000', NULL, 1),
(6713252, 1004768, 58610, '<td valign="top">Lens Baby? Too bad the sky was so flat. Great perspective.</td>', 'Lens Baby? Too bad the sky was so flat. Great perspective.', '2012-03-16 20:53:27.000000', NULL, 1),
(6713261, 1004554, 58610, '<td valign="top">A little to stark for me. Perhaps if you''d taken it just after the sun set, the light would have been just a little softer. Still, a great subject and composition.</td>', 'A little to stark for me. Perhaps if you''d taken it just after the sun set, the light would have been just a little softer. Still, a great subject and composition.', '2012-03-16 20:59:03.000000', NULL, 1),
(6713266, 1004769, 58610, '<td valign="top">One of my favorites. Will definitely be on the front page. Good texture, detail, composition, subject and gradation. My only gripe is the one bright spot in the foreground could  have been toned down just one notch.</td>', 'One of my favorites. Will definitely be on the front page. Good texture, detail, composition, subject and gradation. My only gripe is the one bright spot in the foreground could  have been toned down just one notch.', '2012-03-16 21:06:48.000000', NULL, 1),
(6713268, 1004766, 58610, '<td valign="top">Striking. Good comp, subject and gradation. Simple, but powerful.</td>', 'Striking. Good comp, subject and gradation. Simple, but powerful.', '2012-03-16 21:08:13.000000', NULL, 1),
